<div class="page-head"><div><a class="volver" href="<?= site_url('cotizaciones') ?>">← Volver a cotizaciones</a><p class="eyebrow">COTIZACIÓN · RELACIONES DEL CORE</p><h1><?= esc($titulo) ?></h1><p class="muted">El proveedor y el producto se seleccionan; no se ingresa ninguna clave foránea a mano.</p></div></div>
<section class="card form-card"><form method="post" action="<?= site_url('cotizaciones/guardar') ?>" class="formulario"><?= csrf_field() ?><div class="form-grid"><label>Proveedor<select name="proveedor_id" required><option value="">Selecciona un proveedor</option><?php foreach ($proveedores as $proveedor): ?><option value="<?= (int) $proveedor['id'] ?>" <?= (string) ($datos['proveedor_id'] ?? '') === (string) $proveedor['id'] ? 'selected' : '' ?>><?= esc($proveedor['razon_social']) ?> · <?= esc($proveedor['identificacion_fiscal']) ?></option><?php endforeach; ?></select><small><?= isset($errores['proveedor_id']) ? esc($errores['proveedor_id']) : '' ?></small></label><label>Producto<select name="producto_id" required><option value="">Selecciona un producto</option><?php foreach ($productos as $producto): ?><option value="<?= (int) $producto['id'] ?>" <?= (string) ($datos['producto_id'] ?? '') === (string) $producto['id'] ? 'selected' : '' ?>><?= esc($producto['codigo'] . ' · ' . $producto['nombre']) ?></option><?php endforeach; ?></select><small><?= isset($errores['producto_id']) ? esc($errores['producto_id']) : '' ?></small></label><label>Fecha de emisión<input name="fecha_emision" type="date" required value="<?= esc($datos['fecha_emision'] ?? '', 'attr') ?>"></label><label>Válida hasta<input name="valida_hasta" type="date" required value="<?= esc($datos['valida_hasta'] ?? '', 'attr') ?>"><small><?= isset($errores['valida_hasta']) ? esc($errores['valida_hasta']) : '' ?></small></label><label>Cantidad disponible<input name="cantidad_disponible" type="number" min="1" required value="<?= esc((string) ($datos['cantidad_disponible'] ?? 1), 'attr') ?>"><small><?= isset($errores['cantidad_disponible']) ? esc($errores['cantidad_disponible']) : '' ?></small></label><label>Plazo de entrega (días)<input name="plazo_dias" type="number" min="1" required value="<?= esc((string) ($datos['plazo_dias'] ?? 1), 'attr') ?>"><small><?= isset($errores['plazo_dias']) ? esc($errores['plazo_dias']) : '' ?></small></label><label>Precio unitario<input name="precio_unitario" type="number" min="0" step="0.01" required value="<?= esc($datos['precio_unitario'] ?? '', 'attr') ?>"><small><?= isset($errores['precio_unitario']) ? esc($errores['precio_unitario']) : '' ?></small></label><label>Costo adicional unitario<input name="costo_adicional_unitario" type="number" min="0" step="0.01" required value="<?= esc($datos['costo_adicional_unitario'] ?? '0.00', 'attr') ?>"><small><?= isset($errores['costo_adicional_unitario']) ? esc($errores['costo_adicional_unitario']) : '' ?></small></label></div><div class="form-actions"><a class="boton boton--ghost" href="<?= site_url('cotizaciones') ?>">Cancelar</a><button class="boton boton--primario" type="submit">Guardar cotización <span>→</span></button></div></form></section><?= $this->endSection() ?>
